package io.github.diodeme.ji.host;

import io.github.diodeme.ji.session.model.CanonicalSessionState;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Canonical 30-day trash lifecycle and permanent content-free tombstone contract. */
public final class SessionRetentionPolicy {
    public static final Duration DEFAULT_TRASH_RETENTION = Duration.ofDays(30);
    private final Duration trashRetention;

    public SessionRetentionPolicy(Duration trashRetention) {
        if (trashRetention == null || trashRetention.isNegative()) {
            throw new IllegalArgumentException("trash retention must not be negative");
        }
        this.trashRetention = trashRetention;
    }

    public static SessionRetentionPolicy defaults() {
        return new SessionRetentionPolicy(DEFAULT_TRASH_RETENTION);
    }

    public Record trash(CanonicalSessionState state, long expectedRevision, Instant now) {
        Objects.requireNonNull(state, "state");
        Objects.requireNonNull(now, "now");
        return new Record(state.transition(CanonicalSessionState.SessionStatus.TRASHED,
                Optional.empty(), expectedRevision), Optional.of(now));
    }

    public Record restore(Record record, long expectedRevision, Instant now) {
        Objects.requireNonNull(now, "now");
        if (record.trashedAt().isEmpty()) throw invalid(record.state().sessionId().value(), "not_trashed");
        return new Record(record.state().transition(CanonicalSessionState.SessionStatus.AVAILABLE,
                Optional.empty(), expectedRevision), Optional.empty());
    }

    public Tombstone permanentlyDelete(Record record, long expectedRevision, Instant now) {
        Objects.requireNonNull(now, "now");
        Instant trashedAt = record.trashedAt().orElseThrow(
                () -> invalid(record.state().sessionId().value(), "not_trashed"));
        Instant eligibleAt = trashedAt.plus(trashRetention);
        if (now.isBefore(eligibleAt)) {
            throw new SessionRetentionException("session.retention_not_elapsed", Map.of(
                    "sessionId", record.state().sessionId().value(), "eligibleAt", eligibleAt.toString()));
        }
        CanonicalSessionState deleted = record.state().transition(CanonicalSessionState.SessionStatus.TOMBSTONED,
                Optional.of(CanonicalSessionState.SessionOutcome.DELETED), expectedRevision);
        return new Tombstone(deleted.sessionId().value(), deleted.revision(), deleted.outcome().orElseThrow(), now);
    }

    public void assertCreatable(String sessionId, Optional<Tombstone> tombstone) {
        if (tombstone.filter(value -> value.sessionId().equals(sessionId)).isPresent()) {
            throw new SessionRetentionException("session.tombstoned", Map.of("sessionId", sessionId));
        }
    }

    private static SessionRetentionException invalid(String sessionId, String reason) {
        return new SessionRetentionException("session.retention_invalid", Map.of(
                "sessionId", sessionId, "reason", reason));
    }

    public record Record(CanonicalSessionState state, Optional<Instant> trashedAt) {
        public Record {
            Objects.requireNonNull(state, "state");
            trashedAt = trashedAt == null ? Optional.empty() : trashedAt;
            if ((state.status() == CanonicalSessionState.SessionStatus.TRASHED) != trashedAt.isPresent()) {
                throw new IllegalArgumentException("trash timestamp must match Session lifecycle");
            }
        }
    }

    /** Permanent minimal marker deliberately contains no transcript, workspace, profile, or content fields. */
    public record Tombstone(String sessionId, long revision,
                            CanonicalSessionState.SessionOutcome outcome, Instant deletedAt) {
        public Tombstone {
            if (sessionId == null || sessionId.isBlank() || revision < 0 || outcome == null || deletedAt == null) {
                throw new IllegalArgumentException("invalid Session tombstone");
            }
        }
    }
}
